// Минимальное объявление того куска jsdom, которым пользуется конвейер данных
// (process-map-0c5.4).
//
// ПОЧЕМУ НЕ @types/jsdom. Это была бы новая зависимость, а по CLAUDE.md её
// заводят только через задачу с обоснованием. Обоснования нет: из всего jsdom
// генератору нужен ровно один конструктор и ровно одно поле окна — реализация
// DOMParser, которой в Node нет вовсе. Полный пакет типов принёс бы сотни
// объявлений ради двух строк и ещё одну зависимость, которую надо обновлять.
//
// Заодно это объявление документирует границу: если генератору однажды
// понадобится от jsdom что-то ещё, здесь придётся это дописать — то есть
// расширение поверхности будет видно в ревью, а не растворится в импорте.
declare module 'jsdom' {
  export class JSDOM {
    constructor(html?: string);
    readonly window: { DOMParser: typeof DOMParser };
  }
}
